package io.knowledgebrain.content;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class RecordConceptStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;RecordConceptStore store;BookmarkStore bookmarks;QuestionStore questions;DecisionStore decisions;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="e".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));ds.setUser("brain_content");ds.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));schema="record_concepts_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new RecordConceptStore(ds,Clock.systemUTC());bookmarks=new BookmarkStore(ds,Clock.systemUTC());questions=new QuestionStore(ds,Clock.systemUTC());decisions=new DecisionStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 UUID create(RecordConceptStore.Kind k){return switch(k){case BOOKMARK->bookmarks.create(space,actor,key(),new BookmarkStore.Input("Saved bookmark","https://example.test/","Memo"),trace).bookmark().bookmarkId();case QUESTION->questions.create(space,actor,key(),new QuestionStore.Input("Saved question","Context","","OPEN"),trace).question().questionId();case DECISION->decisions.create(space,actor,key(),new DecisionStore.Input("Saved decision","Context","Choice","Reason","Alternative","DECIDED"),trace).decision().decisionId();};}
 void retire(RecordConceptStore.Kind k,UUID id){switch(k){case BOOKMARK->bookmarks.change(space,id,actor,1,null,true,trace);case QUESTION->questions.change(space,id,actor,1,null,true,trace);case DECISION->decisions.change(space,id,actor,1,null,true,trace);}}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 @Test void eachTypedSourceHasIndependentVersionsStableLinksOrderedAuditAndRetainedArchivedReferences(){for(var k:RecordConceptStore.Kind.values()){var id=create(k);var a=ids.next();var b=ids.next();var zero=store.get(space,k,id);assertEquals(0,zero.links().version());assertNull(zero.links().associationId());assertEquals(zero,store.replace(space,k,id,actor,0,List.of(),trace));var first=store.replace(space,k,id,actor,0,List.of(a,b),trace);assertEquals(1,first.recordVersion());var reordered=store.replace(space,k,id,actor,1,List.of(b,a),trace);assertEquals(first.links().items().reversed(),reordered.links().items());assertEquals(reordered,store.replace(space,k,id,actor,2,List.of(b,a),trace));status(412,()->store.replace(space,k,id,actor,1,List.of(b,a),trace));store.replace(space,k,id,actor,2,List.of(),trace);var readded=store.replace(space,k,id,actor,3,List.of(a),trace);assertNotEquals(first.links().items().getFirst().linkId(),readded.links().items().getFirst().linkId());assertEquals(List.of(4L,3L,2L,1L),store.history(space,k,id,Long.MAX_VALUE,10).stream().map(RecordConceptStore.Revision::version).toList());retire(k,id);var archived=store.get(space,k,id);assertEquals("RETIRED",archived.recordState());assertEquals(readded.links(),archived.links());assertTrue(store.references(space,a,k,"ACTIVE",null,20).items().isEmpty());assertEquals(id,store.references(space,a,k,"RETIRED",null,20).items().getFirst().recordId());status(412,()->store.replace(space,k,id,actor,3,List.of(),trace));status(404,()->store.replace(space,k,id,actor,4,List.of(),trace));}assertEquals(12,count("record_concept_revision"));}
 @Test void parentEditsAndNewActorDoNotRewriteAssociationHistoryOrOriginalBody(){var k=RecordConceptStore.Kind.DECISION;var id=create(k);var original=decisions.get(space,id);var a=ids.next();var first=store.replace(space,k,id,actor,0,List.of(a),trace);assertEquals(original,decisions.get(space,id));var registered=ids.next();var edited=decisions.change(space,id,registered,1,new DecisionStore.Input("Edited source",original.context(),original.outcome(),original.rationale(),original.alternatives(),"DRAFT"),false,trace);assertEquals(first.links(),store.get(space,k,id).links());var second=store.replace(space,k,id,registered,1,List.of(a,ids.next()),trace);var history=store.history(space,k,id,Long.MAX_VALUE,10);assertEquals(registered,history.getFirst().actorId());assertEquals(2,history.getFirst().recordVersion());assertEquals(actor,history.getLast().actorId());assertEquals(1,history.getLast().recordVersion());assertEquals(edited,decisions.get(space,id));assertEquals(second,new RecordConceptStore(ds,Clock.systemUTC()).get(space,k,id));assertEquals(List.of(1L),store.history(space,k,id,2,5).stream().map(RecordConceptStore.Revision::version).toList());}
 @Test void controlledOutboxFailureRollsBackHeadLinksRevisionAndMutation(){var k=RecordConceptStore.Kind.BOOKMARK;var id=create(k);sql.execute("CREATE FUNCTION fail_record_concepts() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.aggregatetype='record-concepts' THEN RAISE EXCEPTION 'controlled record concept failure'; END IF; RETURN NEW; END $$");sql.execute("CREATE TRIGGER fail_record_concepts BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_record_concepts()");assertThrows(RuntimeException.class,()->store.replace(space,k,id,actor,0,List.of(ids.next()),trace));for(String t:List.of("record_concepts","record_concept_link","record_concept_revision"))assertEquals(0,count(t));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_record_concepts");var first=store.replace(space,k,id,actor,0,List.of(ids.next()),trace);sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_record_concepts");assertThrows(RuntimeException.class,()->store.replace(space,k,id,actor,1,List.of(),trace));assertEquals(first,store.get(space,k,id));assertEquals(1,count("record_concept_link"));assertEquals(1,count("record_concept_revision"));}
 @Test void concurrentFirstWritesSerializeOnOwnedParentAndArchivePreventsLaterMutations()throws Exception{var k=RecordConceptStore.Kind.QUESTION;var id=create(k);var target=ids.next();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);Callable<Integer> task=()->{gate.await();try{store.replace(space,k,id,actor,0,List.of(target),trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}};var a=pool.submit(task);var b=pool.submit(task);assertEquals(Set.of(200,412),Set.of(a.get(),b.get()));}assertEquals(1,count("record_concepts"));assertEquals(1,count("record_concept_revision"));retire(k,id);status(404,()->store.replace(space,k,id,actor,1,List.of(ids.next()),trace));assertEquals(List.of(target),store.get(space,k,id).links().items().stream().map(RecordConceptStore.Link::conceptId).toList());}
 @Test void reversePagesUseCurrentSourceTitlesAndBoundSpaceConceptKindAndLifecycle(){var k=RecordConceptStore.Kind.BOOKMARK;var target=ids.next();var sources=new ArrayList<UUID>();for(int n=0;n<23;n++){var id=create(k);sources.add(id);store.replace(space,k,id,actor,0,List.of(target),trace);}var q=create(RecordConceptStore.Kind.QUESTION);store.replace(space,RecordConceptStore.Kind.QUESTION,q,actor,0,List.of(target),trace);var first=store.references(space,target,k,"ACTIVE",null,20);var last=store.references(space,target,k,"ACTIVE",first.nextAfter(),20);assertEquals(20,first.items().size());assertEquals(3,last.items().size());assertNull(last.nextAfter());status(400,()->store.references(actor,target,k,"ACTIVE",first.nextAfter(),20));status(400,()->store.references(space,ids.next(),k,"ACTIVE",first.nextAfter(),20));status(400,()->store.references(space,target,RecordConceptStore.Kind.QUESTION,"ACTIVE",first.nextAfter(),20));status(400,()->store.references(space,target,k,"RETIRED",first.nextAfter(),20));var id=sources.getFirst();bookmarks.change(space,id,actor,1,new BookmarkStore.Input("Renamed source","https://example.test/","Memo"),false,trace);assertEquals("Renamed source",store.references(space,target,k,"ACTIVE",null,20).items().getFirst().title());status(404,()->store.get(space,RecordConceptStore.Kind.QUESTION,id));status(404,()->store.get(actor,k,id));assertTrue(store.references(actor,target,k,"ACTIVE",null,20).items().isEmpty());}
 @Test void duplicateInvalidOrExcessiveIdsNeverReserveAssociation(){var k=RecordConceptStore.Kind.DECISION;var id=create(k);var a=ids.next();for(var invalid:List.of(List.of(a,a),List.of(UUID.randomUUID()),java.util.stream.IntStream.range(0,21).mapToObj(n->ids.next()).toList()))status(400,()->store.replace(space,k,id,actor,0,invalid,trace));status(400,()->RecordConceptStore.Kind.parse("NOTE"));status(400,()->store.replace(space,k,id,actor,-1,List.of(),trace));assertEquals(0,count("record_concepts"));assertEquals(1,decisions.get(space,id).version());}
}
